": [\\n                    3\\n                ],\\n                \"comment\": \"类别，目前支持 OTP/TRANSACTIONAL/MARKETING\",\\n                \"repeat\": 2\\n            },\\n            \"components\": {\\n                \"notnull\": true,\\n                \"type\": \"array\",\\n                \"valueLevel\": 0,\\n                \"lengthLevel\": 1,\\n                \"lengths\": [\\n                    4\\n                ],\\n                \"values\": [\\n                    {\\n                        \"0\": {\\n                            \"type\": \"object\",\\n                            \"notnull\": true,\\n                            \"comment\": \"模板内容\",\\n                            \"values\": [\\n                                {\\n                                    \"type\": \"number\",\\n                                    \"notnull\": false,\\n                                    \"text\": {\\n                                        \"type\": \"string\",\\n                                        \"notnull\": true,\\n                                        \"comment\": \"两个大括号{{}}括起来的表示模板变量\"\\n                                    },\\n                                    \"format\": {\\n                                        \"type\": \"string\",\\n                                        \"notnull\": true,\\n                                        \"comment\": \"类型，支持 text/image/location/video/document，默认TEXT\"\\n                                    },\\n                                    \"example\": {\\n                                        \"values\": [\\n                                            {\\n                                                \"type\": \"number\",\\n                                                \"notnull\": false,\\n                                                \"header_handle\": {\\n                                                    \"values\": [\\n                                                        {\\n                                                            \"0\": {\\n                                                                \"type\": \"string\",\\n                                                                \"notnull\": true,\\n                                                                \"comment\": \"jiguang.cn/demopic.jpg\\\"\"\\n                                                            },\\n                                                            \"type\": \"array\",\\n                                                            \"notnull\": false\\n                                                        }\\n                                                    ]\\n                                                }\\n                                            }\\n                                        ]\\n                                    },\\n                                    \"buttons\": {\\n                                        \"values\": [\\n                                            {\\n                                                \"0\": {\\n                                                    \"values\": [\\n                                                        {\\n                                                            \"type\": \"number\",\\n                                                            \"notnull\": false\\n                                                        }\\n                                                    ]\\n                                                },\\n                                                \"type\": \"array\",\\n                                                \"notnull\": false\\n                                            }\\n                                        ]\\n                                    }\\n                                }\\n                            ]\\n                        },\\n                        \"notnull\": true,\\n                        \"type\": \"object\",\\n                        \"valueLevel\": 0,\\n                        \"values\": [\\n                            {\\n                                \"type\": {\\n                                    \"notnull\": true,\\n                                    \"type\": \"string\",\\n                                    \"valueLevel\": 0,\\n                                    \"values\": [\\n                                        \"BODY\",\\n                                        \"HEADER\",\\n                                        \"FOOTER\",\\n                                        \"BUTTONS\"\\n                                    ],\\n                                    \"lengthLevel\": 1,\\n                                    \"lengths\": [\\n                                        7,\\n                                        6,\\n                                        4\\n                                    ],\\n                                    \"repeat\": 9\\n                                },\\n                                \"text\": {\\n                                    \"notnull\": false,\\n                                    \"type\": \"string\",\\n                                    \"valueLevel\": 3,\\n                                    \"values\": [],\\n                                    \"lengthLevel\": 1,\\n                                    \"lengths\": [\\n                                        41,\\n                                        19\\n                                    ],\\n                                    \"repeat\": 2\\n                                },\\n                                \"example\": {\\n                                    \"notnull\": false,\\n                                    \"type\": \"object\",\\n                                    \"valueLevel\": 0,\\n                                    \"values\": [\\n                                        {\\n                                            \"body_text\": {\\n                                                \"notnull\": false,\\n                                                \"type\": \"array\",\\n                                                \"valueLevel\": 0,\\n                                                \"lengthLevel\": 1,\\n                                                \"lengths\": [\\n                                                    1\\n                                                ],\\n                                                \"values\": [\\n                                                    {\\n                                                        \"notnull\": true,\\n                                                        \"type\": \"array\",\\n                                                        \"valueLevel\": 0,\\n                                                        \"lengthLevel\": 1,\\n                                                        \"lengths\": [\\n                                                            1\\n                                                        ],\\n                                                        \"values\": [\\n                                                            {\\n                                                                \"notnull\": true,\\n                                                                \"type\": \"string\",\\n                                                                \"valueLevel\": 3,\\n                                                                \"values\": [],\\n                                                                \"lengthLevel\": 1,\\n                                                                \"lengths\": [\\n                                                                    4\\n                                                                ],\\n                                                                \"repeat\": 1\\n                                                            }\\n                                                        ],\\n                                                        \"repeat\": 1\\n                                                    }\\n                                                ],\\n                                                \"repeat\": 1\\n                                            },\\n                                            \"header_handle\": {\\n                                                \"notnull\": false,\\n                                                \"type\": \"array\",\\n                                                \"valueLevel\": 0,\\n                                                \"lengthLevel\": 1,\\n                                                \"lengths\": [\\n                                                    1\\n                                                ],\\n                                                \"values\": [\\n                                                    {\\n                                                        \"notnull\": true,\\n                                                        \"type\": \"string\",\\n                                                        \"valueLevel\": 3,\\n                                                        \"values\": [],\\n                                                        \"lengthLevel\": 1,\\n                                                        \"lengths\": [\\n                                                            30\\n                                                        ],\\n                                                        \"repeat\": 1\\n                                                    }\\n                                                ],\\n                                                \"repeat\": 1\\n                                            }\\n                                        }\\n                                    ]\\n                                },\\n                                \"format\": {\\n                                    \"notnull\": false,\\n                                    \"type\": \"string\",\\n                                    \"valueLevel\": 3,\\n                                    \"values\": [],\\n                                    \"lengthLevel\": 1,\\n                                    \"lengths\": [\\n                                        5\\n                                    ],\\n                                    \"repeat\": 1\\n                                },\\n                                \"buttons\": {\\n                                    \"notnull\": false,\\n                                    \"type\": \"array\",\\n                                    \"valueLevel\": 0,\\n                                    \"lengthLevel\": 1,\\n                                    \"lengths\": [\\n                                        1\\n                                    ],\\n                                    \"values\": [\\n                                        {\\n                                            \"notnull\": true,\\n                                            \"type\": \"object\",\\n                                            \"valueLevel\": 0,\\n                                            \"values\": [\\n                                                {\\n                                                    \"type\": {\\n                                                        \"notnull\": true,\\n                                                        \"type\": \"string\",\\n                                                        \"valueLevel\": 0,\\n                                                        \"values\": [\\n                                                            \"PHONE_NUMBER\"\\n                                                        ],\\n                                                        \"lengthLevel\": 1,\\n                                                        \"lengths\": [\\n                                                            12\\n                                                        ],\\n                                                        \"repeat\": 2\\n                                                    },\\n                                                    \"text\": {\\n                                                        \"notnull\": true,\\n                                                        \"type\": \"string\",\\n                                                        \"valueLevel\": 3,\\n                                                        \"values\": [],\\n                                                        \"lengthLevel\": 1,\\n                                                        \"lengths\": [\\n                                                            22\\n                                                        ],\\n                                                        \"repeat\": 1\\n                                                    },\\n                                                    \"phone_number\": {\\n                                                        \"notnull\": true,\\n                                                        \"type\": \"string\",\\n                                                        \"valueLevel\": 3,\\n                                                        \"values\": [],\\n                                                        \"lengthLevel\": 1,\\n                                                        \"lengths\": [\\n                                                            13\\n                                                        ],\\n                                                        \"repeat\": 1\\n                                                    }\\n                                                }\\n                                            ]\\n                                        }\\n                                    ],\\n                                    \"repeat\": 1\\n                                }\\n                            }\\n                        ],\\n                        \"components\": {\\n                            \"type\": \"array\",\\n                            \"notnull\": true,\\n                            \"comment\": \"模板具体内容，可包含 HEADER/BODY/FOOTER/BUTTON\"\\n                        }\\n                    }\\n                ],\\n                \"repeat\": 1,\\n                \"comment\": \"模板具体内容，可包含 HEADER/BODY/FOOTER/BUTTON\"\\n            },\\n            \"id\": {\\n                \"type\": \"string\",\\n                \"notnull\": true,\\n                \"comment\": \"模板id\"\\n            },\\n            \"status\": {\\n                \"type\": \"string\",\\n                \"notnull\": true,\\n                \"comment\": \"状态，APPROVED为审核通过可用\"\\n            },\\n            \"type\": {\\n                \"type\": \"string\",\\n                \"notnull\": true,\\n                \"comment\": \"内容块，目前支持 HEADER/BODY/FOOTER/BUTTONS\"\\n            },\\n            \"text\": {\\n                \"type\": \"string\",\\n                \"notnull\": true,\\n                \"comment\": \"具体文本，当body为text时不需要传format字段\"\\n            },\\n            \"format\": {\\n                \"type\": \"string\",\\n                \"notnull\": true,\\n                \"comment\": \"内容类型，支持 text/image/video/document/location\"\\n            },\\n            \"example\": {\\n                \"values\": [\\n                    {\\n                        \"type\": \"number\",\\n                        \"notnull\": false,\\n                        \"header_url\": {\\n                            \"type\": \"string\",\\n                            \"notnull\": true,\\n                            \"comment\": \"jiguang.cn/demopic.jpg\\\"]\"\\n                        }\\n                    }\\n                ]\\n            }\\n        }\\n    ]\\n}','Authorization: Basic amlndWFuZ2RldjpkZXZfc2VjcmV0 // 上述 base64_auth_string 的生成算法为：base64(dev_key:dev_secret)Header 名称是 \"Authorization\"，值是 base64 转换过的 \"username:password\" 对（中间有个冒号）。在 WhatsApp API 的场景里，username 是 DevKey，password 是 DevSecret。请在控制台-配置管理- API 密钥 页面获取。','2023-04-25 15:18:29',NULL,'\\n## 概述\\n使用模板管理 API 可以对 WABA 的模板进行增删改查操作。\\n## 调用验证\\nEngageLab REST API 采用 [HTTP 基本认证](http://zh.wikipedia.org/wiki/HTTP%E5%9F%BA%E6%9C%AC%E8%AE%A4%E8%AF%81) 的验证方式：HTTP Header（头）里加 Authorization：\\n```\\nAuthorization: Basic ${base64_auth_string}\\n```\\n上述 base64_auth_string 的生成算法为：base64(dev_key:dev_secret)\\n\\n- Header 名称是 \"Authorization\"，值是 base64 转换过的 \"username:password\" 对（中间有个冒号）。\\n- 在 WhatsApp API 的场景里，username 是 DevKey，password 是 DevSecret。请在控制台-配置管理- [API 密钥](/zh_CN/docs/whatsapp/console/configuration-management/api-keys) 页面获取。\\n## 获取模板\\n### 调用地址\\n`GET https://wa.api.engagelab.cc/v1/templates`\\n### 返回示例\\n```\\n// 一个 json 数组，数组中每一个对象都是模板信息\\n[\\n    {\\n        \"id\": \"406979728071589\", // 模板id\\n        \"name\": \"code\", // 模板名称\\n        \"language\": \"zh_CN\", // 模板语言\\n        \"status\": \"APPROVED\", // 状态，APPROVED为审核通过可用\\n        \"category\": \"OTP\", // 类别，目前支持 OTP/TRANSACTIONAL/MARKETING\\n        \"components\": [ // 模板具体内容，可包含 HEADER/BODY/FOOTER/BUTTON\\n            {\\n                \"type\": \"HEADER\",\\n                \"format\": \"text\", // 类型，支持 text/image/location/video/document，默认TEXT\\n                \"text\": \"注册验证码\" // 文本内容，当format为text时，为必选项\\n            },\\n            {\\n                \"type\": \"BODY\",\\n                \"text\": \"您的验证码是 {{1}}，请于 5 分钟内输入。\" // 两个大括号{{}}括起来的表示模板变量\\n            }\\n        ]\\n    },\\n    ......\\n]\\n```\\n### 返回参数\\n| **参数** | **类型** | **选项** | **说明** |\\n| --- | --- | --- | --- |\\n| id | String | 必填 | 模板 ID |\\n| name | String | 必填 | 模板名字 |\\n| language | String | 必填 | 模板语言，参见 [语言代码](#语言代码)  。 |\\n| category | String | 必填 | 模板类别。<li>OTP：一次性密码<li>MARKETING：市场营销<li>TRANSACTIONAL：交易事务<br />**注意：模板类别最晚在 2023 年 5 月 1 日更新为：**<li>AUTHENTICATION<li>MARKETING<li>UTILITY<br /> |\\n| components | Object Array | 必填 | 模板内容的组件，参考 [创建模板中的 components 对象](#components-对象) |\\n| status | String | 必填 | 模板状态：<br />APPROVED, IN_APPEAL, PENDING, REJECTED, PENDING_DELETION, DELETED, DISABLED, PAUSED, LIMIT_EXCEEDED |\\n\\n\\n## 创建模板\\n### 调用地址\\n`POST https://wa.api.engagelab.cc/v1/templates`\\n### 调用示例\\n```\\n{\\n    \"name\": \"template_name\", // 模板名称，允许同名模板，仅支持小写字母及数字及下划线\\n    \"language\": \"zh_CN\", // 模板语言，同名模板下不允许同语言模板\\n    \"category\": \"OTP\", // 类别，目前支持 OTP/TRANSACTIONAL/MARKETING\\n    \"components\": [\\n        { // 模板内容\\n            \"type\": \"BODY\", // 内容块，目前支持 HEADER/BODY/FOOTER/BUTTONS\\n            \"text\": \"define var as {{1}}\" // 具体文本，当body为text时不需要传format字段\\n      	\"example\": {\\n                \"body_text\": [\\n                    [\\n                        \"var1\"\\n                    ]\\n                ]\\n            }\\n        },\\n        {\\n            \"type\": \"HEADER\",\\n            \"format\": \"image\", // 内容类型，支持 text/image/video/document/location\\n            \"example\": {\\n                \"header_handle\": [\\n                    \"https://jiguang.cn/demopic.jpg\"\\n                ]\\n            }\\n        },\\n        {\\n            \"type\": \"FOOTER\",\\n            \"text\": \"footer only support text without variable\"\\n        },\\n        {\\n            \"type\": \"BUTTONS\",\\n            \"buttons\": [\\n                {\\n                    \"type\": \"PHONE_NUMBER\", // 按钮类型，支持 PHONE_NUMBER/URL/QUICK_REPLY              \\n                    \"text\": \"this is a phone number\",\\n                    \"phone_number\": \"8613800138000\"\\n                }\\n            ]\\n        }\\n    ]\\n}\\n```\\n### 请求参数\\n| **参数** | **类型** | **选项** | **说明** |\\n| --- | --- | --- | --- |\\n| name | String | 必填 | 模版名字，仅支持小写字母、数字及下划线，不超过 512 个字符。 |\\n| language | String | 必填 | 模版语言，参见 [语言代码](#语言代码)  。 |\\n| category | String | 必填 | 模版类别。<li>OTP：一次性密码<li>MARKETING：市场营销<li>TRANSACTIONAL：交易事务<br />**注意：模板类别最晚在 2023 年 5 月 1 日更新为：**<li>AUTHENTICATION<li>MARKETING<li>UTILITY<br /> |\\n| components | Object Array | 必填 | 描述模板内容的组件，参考 [components 对象](#components-对象) 说明；注意必须包含 type=BODY 的 components。 |\\n\\n#### components 对象\\n本对象用于描述模板内容。模板分为「页眉 HEADER」「正文 BODY」「页脚 FOOTER」「按钮 BUTTONS」几个组件，使用 type 来指定，不同的组件类型支持的参数不同，如下：\\n##### header 页眉组件\\nheader 组件整体是可选的，如果不需要设置页眉，请不要设置此组件\\n\\n| **参数** | **类型** | **选项** | **说明** |\\n| --- | --- | --- | --- |\\n| type | String | 必填 | 组件类型，取值 HEADER |\\n| format | String | 必填 | 页眉格式，取值：text、image、video、document，对应着文本、图片、视频、文件。 |\\n| text | String | 可选 | 页眉文本内容，当 format=text 时需设置此字段内容。页眉文本内容中可以设置变量，但仅支持设置 1 个变量，用 {{1}} 进行表示。 |\\n| example | JSON Object | 可选 | 页眉示例，当 text 包含变量或 format 为媒体类型时，此字段必填。参考 [example 对象说明](#example-对象说明) |\\n\\n###### example 对象说明\\n| **参数** | **类型** | **选项** | **说明** |\\n| --- | --- | --- | --- |\\n| header_handle | String Array | 可选 | 当 format 为 image、video、document 时，对此字段传入对应类型的媒体的 url，且 url 能被访问，否则模版审核可能被拒绝。<br />例如：\"header_handle\": [\"`https://jiguang.cn/demopic.jpg`\"] |\\n| header_text | String Array | 可选 | 当 format 为 text 且包含变量时，对此字段传入该变量的替换值。例如：\"header_text\": [\"var1\"] |\\n| header_url | String Array | 可选 | 与header_handle的用法一致，注意此字段在 WhatsApp  未来的版本中将不再支持，尽量避免使用。<br />例如：\"header_url\": [\"`https://jiguang.cn/demopic.jpg`\"] |\\n\\n##### body 正文组件\\nbody 组件是必填的，必须设置正文内容。\\n\\n| **参数** | **类型** | **选项** | **说明** |\\n| --- | --- | --- | --- |\\n| type | String | 必填 | 组件类型，取值 BODY |\\n| text | String | 必填 | 正文内容，最长不超过 个字符，支持设置多个变量，变量由两个大括号加变量序号组成，序号序号需要从 1 开始，保持递增，如 {{1}} 和 {{2}} 。 |\\n| example | JSON Object | 可选 | 正文示例，Meta 审核人员将根据示例判断你的消息合规性。参考 [example 对象说明](#example-对象说明-1)，当 text 包含变量时，此字段必填。 |\\n\\n###### example 对象说明\\n| **参数** | **类型** | **选项** | **说明** |\\n| --- | --- | --- | --- |\\n| body_text | String Array | 可选 | 当 text 包含变量时，需要对此字段传入**所有变量**的替换值，按变量序号的顺序依次填写。例如：\"body_text\": [[\"var1\",\"var2\",\"var3\"]] |\\n\\n##### footer 页脚组件\\nfooter 组件整体是可选的，如果不需要设置页脚，请不要设置此组件\\n\\n| **参数** | **类型** | **选项** | **说明** |\\n| --- | --- | --- | --- |\\n| type | String | 必填 | 组件类型，取值 FOOTER |\\n| text | String | 必填 | 页脚内容，只能设置纯文本内容，**不能定义变量。** |\\n\\n##### buttons 按钮组件\\nbuttons 组件整体是可选的，如果不需要设置按钮，请不要设置此组件\\n\\n| **参数** | **类型** | **选项** | **说明** |\\n| --- | --- | --- | --- |\\n| type | String | 必填 | 组件类型，取值 BUTTONS |\\n| buttons | Object Array | 必填 | 按钮信息，参考 [buttons 对象说明](#buttons-对象说明)。 |\\n\\n###### buttons 对象说明\\n| **参数** | **类型** | **选项** | **说明** |\\n| --- | --- | --- | --- |\\n| type | String | 必填 | 按钮类型，取值： QUICK_REPLY、URL、PHONE_NUMBER，对应：快速回复、浏览网站、拨打电话号码 |\\n| text | String | 必填 | 按钮上的文字说明，**不能包含变量，为纯文本，最长 25 个字符** |\\n| url | String | 可选 | 当 type=URL 时必填，可以在网址的结尾设置变量，且仅支持设置 1 个变量，用 {{1}} 进行表示。 |\\n| phone_number | String | 可选 | 当 type=PHONE_NUMBER 时必填，**不能包含变量**，内容为包含国际区号的电话号码。 |\\n| example | String Array | 可选 | 当 type=QUICK_REPLY 和 type=URL 时必填<br />例如：\"example\": [\"`https://www.website.com/dynamic-url-example`\"] |\\n\\n### 返回参数\\n#### 成功返回\\n| **参数** | **类型** | **选项** | **说明** |\\n| --- | --- | --- | --- |\\n| template_id | String | 必填 | 模板 ID，成功时返回 |\\n\\n```\\n{\\n    \"template_id\": \"1275172986566180\"		// 模板id\\n}\\n```\\n#### 失败返回\\n| **参数** | **类型** | **选项** | **说明** |\\n| --- | --- | --- | --- |\\n| code | int | 必填 | 错误码，失败时返回 |\\n| message | String | 必填 | 错误信息，失败时返回 |\\n\\n```\\n{\\n    \"code\": 5002,\\n    \"message\": \"Invalid parameter. code:100:2388042\"\\n}\\n```\\n## 更新模板\\n### 调用地址\\n`PUT  https://wa.api.engagelab.cc/v1/templates/{templateId}`\\n### 调用示例\\n```\\n{\\n   \"components\": [{						// 模板内容\\n        \"type\": \"BODY\",					// 内容块，目前支持 HEADER/BODY/FOOTER/BUTTONS\\n        \"text\": \"define var as {{1}}\" // 具体文本，当body为text时不需要传format字段\\n      	\"example\": {\\n          	\"body_text\": [[\"var1\"]]\\n        }\\n    },{\\n        \"type\": \"HEADER\",\\n        \"format\": \"image\",				// 内容类型，支持 text/image/video/document/location\\n      	\"example\": {\\n          	\"header_url\": [\"https://jiguang.cn/demopic.jpg\"]\\n      	}\\n    },{\\n				\"type\": \"FOOTER\",\\n				\"text\": \"footer only support text without variable\"\\n		},{\\n      	\"type\": \"BUTTONS\",\\n      	\"buttons\": [{                                    \\n            \"type\": \"PHONE_NUMBER\",         	// 按钮类型，支持 PHONE_NUMBER/URL/QUICK_REPLY              \\n            \"text\": \"this is a phone number\",             \\n            \"phone_number\": \"8613800138000\"\\n    		}]\\n  	}]\\n}\\n```\\n### 请求参数\\n同创建模版接口的 [请求参数](/zh_CN/docs/whatsapp/rest-api/send-message-api#请求参数)。\\n### 返回参数\\n#### 成功返回\\n| **参数** | **类型** | **选项** | **说明** |\\n| --- | --- | --- | --- |\\n| code | int | 必填 | 返回码，固定为 0 |\\n| message | String | 必填 | 返回信息，固定为success |\\n\\n```\\n{\\n    \"code\": 0,\\n    \"message\": \"success\"\\n}\\n```\\n#### 失败返回\\n| **参数** | **类型** | **选项** | **说明** |\\n| --- | --- | --- | --- |\\n| code | int | 必填 | 错误码，失败时返回 |\\n| message | String | 必填 | 错误信息，失败时返回 |\\n\\n```\\n{\\n    \"code\": 5002,\\n    \"message\": \"Invalid parameter. code:100:2593002\"\\n}\\n```\\n## 删除模板\\n### 调用地址\\n`DELETE https://wa.api.engagelab.cc/v1/templates/{template_name}`<br />**注意：此处传递的是模板名称并非模板 ID，将删除该模板名称的所有语言的模板内容**\\n### 返回参数\\n#### 成功返回\\n| **参数** | **类型** | **选项** | **说明** |\\n| --- | --- | --- | --- |\\n| code | int | 必填 | 返回码，固定为 0 |\\n| message | String | 必填 | 返回信息，固定为success |\\n\\n```\\n{\\n    \"code\": 0,\\n    \"message\": \"success\"\\n}\\n\\n\\n```\\n#### 失败返回\\n| **参数** | **类型** | **选项** | **说明** |\\n| --- | --- | --- | --- |\\n| code | int | 必填 | 错误码，失败时返回 |\\n| message | String | 必填 | 错误信息，失败时返回 |\\n\\n```\\n{\\n    \"code\": 2004,\\n    \"message\": \"something error\"\\n}\\n```\\n## 错误码\\n| **错误码** | **http code** | **说明** |\\n| --- | --- | --- |\\n| 1000 | 500 | 内部错误 |\\n| 2001 | 401 | EngageLab 侧鉴权失败，未携带有效数据格式的 token |\\n| 2002 | 401 | EngageLab 侧鉴权失败，token已过期或已被禁用 |\\n| 2003 | 400 | WhatsApp 侧鉴权失败，请联系 EngageLab 客服处理 |\\n| 2004 | 403 | 无调用此 API 的权限 |\\n| 3001 | 400 | 请求参数格式无效，请检查是否采用 JSON 格式 |\\n| 3002 | 400 | 请求参数有误，请检查请求参数是否符合要求 |\\n| 3003 | 400 | 请求参数有误，相关业务校验失败 |\\n| 4001 | 400 | 模板不存在 |\\n| 5002 | 400 | 模板请求在 Meta 处理失败，详情参考 message 字段的错误描述 |\\n\\n## 注释\\n### 媒体消息格式要求\\n| **媒体类型** | **支持的格式类型 Content-Type** | 大小限制 |\\n| --- | --- | --- |\\n| image | image/jpeg, image/png，不支持透明背景 | 5 MB |\\n| video | video/mp4 | 16MB  |\\n| document | 仅支持 PDF 格式 | 100 MB |\\n\\n### 语言代码\\n相关语言和对应代码的对应关系，请下载本文件查看：<br />[模板语言代码.xlsx](https://jiguang-docs.yuque.com/attachments/yuque/0/2023/xlsx/22807620/1678245419907-04fb4943-9163-4e9c-b106-4eab82e85a1c.xlsx?_lake_card=%7B%22src%22%3A%22https%3A%2F%2Fjiguang-docs.yuque.com%2Fattachments%2Fyuque%2F0%2F2023%2Fxlsx%2F22807620%2F1678245419907-04fb4943-9163-4e9c-b106-4eab82e85a1c.xlsx%22%2C%22name%22%3A%22%E6%A8%A1%E6%9D%BF%E8%AF%AD%E8%A8%80%E4%BB%A3%E7%A0%81.xlsx%22%2C%22size%22%3A12877%2C%22ext%22%3A%22xlsx%22%2C%22source%22%3A%22%22%2C%22status%22%3A%22done%22%2C%22download%22%3Atrue%2C%22taskId%22%3A%22udb22a932-8729-46db-8e94-c69e0d4a20f%22%2C%22taskType%22%3A%22transfer%22%2C%22type%22%3A%22application%2Fvnd.openxmlformats-officedocument.spreadsheetml.sheet%22%2C%22mode%22%3A%22title%22%2C%22id%22%3A%22ua06120a3%22%2C%22card%22%3A%22file%22%7D)'),(1682436186370,0,0,82002,'APIJSON.cn',0,3,NULL,'消息发送 API',NULL,'POST','JSON','/v1/messages','{\\n    \"from\": \"+8613800138000\",\\n    \"to\": [\\n        \"00447911123456\"\\n    ],\\n    \"body\": {\\n        \"type\": \"template\",\\n        \"template\": {\\n            \"name\": \"code\",\\n            \"language\": \"zh_CN\",\\n            \"components\": [\\n                {\\n                    \"type\": \"body\",\\n                    \"parameters\": [\\n                        {\\n                            \"type\": \"text\",\\n                            \"text\": \"12345\"\\n                        }\\n                    ]\\n                }\\n            ]\\n        },\\n        \"image\": {\\n            \"id\": \"1\",\\n            \"link\": \"https://img.jiguang.cn/jiguang/public/img/c866bd2.png\",\\n            \"caption\": \"caption info\"\\n        },\\n        \"video\": {\\n            \"id\": \"1\",\\n            \"link\": \"https://img.jiguang.cn/jiguang/public/videos/432acc5.mp4\",\\n            \"caption\": \"caption info\"\\n        },\\n        \"audio\": {\\n            \"id\": \"1\",\\n            \"link\": \"https://file-examples.com/storage/fe5947fd2362fc197a3c2df/2017/11/file_example_MP3_700KB.mp3\"\\n        },\\n        \"document\": {\\n            \"id\": \"1\",\\n            \"link\": \"https://img.jiguang.cn/jiguang/public/videos/432acc5.mp4\",\\n            \"caption\": \"caption info\",\\n            \"filename\": \"document file name\"\\n        },\\n        \"sticker\": {\\n            \"id\": \"1\",\\n            \"link\": \"http://sample-file.bazadanni.com/download/images/webp/sample.webp\"\\n        }\\n    },\\n    \"request_id\": \"123asdbbqwe9faweg\",\\n    \"custom_args\": {\\n        \"arg1\": \"string val\",\\n        \"arg2\": 123\\n    }\\n}',NULL,NULL,'{\\n    \"notnull\": true,\\n    \"type\": \"object\",\\n    \"valueLevel\": 0,\\n    \"values\": [\\n        {\\n            \"from\": {\\n                \"notnull\": true,\\n                \"type\": \"string\",\\n                \"valueLevel\": 3,\\n                \"values\": [],\\n                \"lengthLevel\": 1,\\n                \"lengths\": [\\n                    14\\n                ],\\n                \"comment\": \"发送方的电话号码\",\\n                \"repeat\": 11\\n            },\\n            \"to\": {\\n                \"notnull\": true,\\n                \"type\": \"array\",\\n                \"valueLevel\": 0,\\n                \"lengthLevel\": 1,\\n                \"lengths\": [\\n                    1\\n                ],\\n                \"values\": [\\n                    {\\n                        \"notnull\": true,\\n                        \"type\": \"string\",\\n                        \"valueLevel\": 3,\\n                        \"values\": [],\\n                        \"lengthLevel\": 1,\\n                        \"lengths\": [\\n                            14\\n                        ],\\n                        \"to\": {\\n                            \"type\": \"array\",\\n                            \"notnull\": true,\\n                            \"comment\": \"收件人的电话号码\"\\n                        },\\n                        \"repeat\": 11\\n                    }\\n                ],\\n                \"comment\": \"收件人的电话号码\",\\n                \"repeat\": 11\\n            },\\n            \"body\": {\\n                \"notnull\": true,\\n                \"type\": \"object\",\\n                \"valueLevel\": 0,\\n                \"values\": [\\n                    {\\n                        \"type\": {\\n                            \"notnull\": true,\\n                            \"type\": \"string\",\\n                            \"valueLevel\": 3,\\n                            \"values\": [],\\n                            \"lengthLevel\": 1,\\n                            \"lengths\": [\\n                                8\\n                            ],\\n                            \"comment\": \"消息类型\",\\n                            \"repeat\": 11\\n                        },\\n                        \"template\": {\\n                            \"notnull\": true,\\n                            \"type\": \"object\",\\n                            \"valueLevel\": 0,\\n                            \"values\": [\\n                                {\\n                                    \"name\": {\\n                                        \"notnull\": true,\\n                                        \"type\": \"string\",\\n                                        \"valueLevel\": 3,\\n                                        \"values\": [],\\n                                        \"lengthLevel\": 1,\\n                                        \"lengths\": [\\n                                            4\\n                                        ],\\n                                        \"repeat\": 11,\\n                                        \"comment\": \"模板名称。可以在控制台-消息模板页面找到，仅支持小写数字及下划线。\"\\n                                    },\\n                                    \"language\": {\\n                                        \"notnull\": true,\\n                                        \"type\": \"string\",\\n                                        \"valueLevel\": 3,\\n                                        \"values\": [],\\n                                        \"lengthLevel\": 1,\\n                                        \"lengths\": [\\n                                            5\\n                                        ],\\n                                        \"repeat\": 11,\\n                                        \"comment\": \"模板 语言代码。创建模板时对同一个模板名称可以设置多个语言的内容，因此发送时需要使用 name 和 language 字段共同决定所选模板。\"\\n                                    },\\n                                    \"components\": {\\n                                        \"notnull\": false,\\n                                        \"type\": \"array\",\\n                                        \"valueLevel\": 0,\\n                                        \"lengthLevel\": 1,\\n                                        \"lengths\": [\\n                                            1\\n                                        ],\\n                                        \"values\": [\\n                                            {\\n                                                \"0\": {\\n                                                    \"values\": [\\n                                                        {\\n                                                            \"type\": \"number\",\\n                                                            \"notnull\": false,\\n                                                            \"parameters\": {\\n                                                                \"values\": [\\n                                                                    {\\n                                                                        \"0\": {\\n                                                                            \"values\": [\\n                                                                                {\\n                                                                                    \"type\": \"number\",\\n                                                                                    \"notnull\": false\\n                                                                                }\\n                                                                            ]\\n                                                                        },\\n                                                                        \"type\": \"array\",\\n                                                                        \"notnull\": false\\n                                                                    }\\n                                                                ]\\n                                                            }\\n                                                        }\\n                                                    ]\\n                                                },\\n                                                \"notnull\": true,\\n                                                \"type\": \"object\",\\n                                                \"valueLevel\": 0,\\n                                                \"values\": [\\n                                                    {\\n                                                        \"type\": {\\n                                                            \"notnull\": true,\\n                                                            \"type\": \"string\",\\n                                                            \"valueLevel\": 3,\\n                                                            \"values\": [],\\n                                                            \"lengthLevel\": 1,\\n                                                            \"lengths\": [\\n                                                                4\\n                                                            ],\\n                                                            \"repeat\": 11\\n                                                        },\\n                                                        \"parameters\": {\\n                                                            \"notnull\": true,\\n                                                            \"type\": \"array\",\\n                                                            \"valueLevel\": 0,\\n                                                            \"lengthLevel\": 1,\\n                                                            \"lengths\": [\\n                                                                1\\n                                                            ],\\n                                                            \"values\": [\\n                                                                {\\n                                                                    \"notnull\": true,\\n                                                                    \"type\": \"object\",\\n                                                                    \"valueLevel\": 0,\\n                                                                    \"values\": [\\n                                                                        {\\n                                                                            \"type\": {\\n                                                                                \"notnull\": true,\\n                                                                                \"type\": \"string\",\\n                                                                                \"valueLevel\": 3,\\n                                                                                \"values\": [],\\n                                                                                \"lengthLevel\": 1,\\n                                                                                \"lengths\": [\\n                                                                                    4\\n                                                                                ],\\n                                                                                \"repeat\": 11\\n                                                                            },\\n                                                                            \"text\": {\\n                                                                                \"notnull\": true,\\n                                                                                \"type\": \"string\",\\n                                                                                \"valueLevel\": 3,\\n                                                                                \"values\": [],\\n                                                                                \"lengthLevel\": 1,\\n                                                                                \"lengths\": [\\n                                                                                    5\\n                                                                                ],\\n                                                                                \"repeat\": 11\\n                                                                            }\\n                                                                        }\\n                                                                    ]\\n                                                                }\\n                                                            ],\\n                                                            \"repeat\": 11\\n                                                        }\\n                                                    }\\n                                                ],\\n                                                \"components\": {\\n                                                    \"type\": \"array\",\\n                                                    \"notnull\": false,\\n                                                    \"comment\": \" 当模板中存在可变变量时，需要填充此字段，数组中仅设置 1 个 components 对象元素即可。\"\\n                                                }\\n                                            }\\n                                        ],\\n                                        \"repeat\": 11,\\n                                        \"comment\": \" 当模板中存在可变变量时，需要填充此字段，数组中仅设置 1 个 components 对象元素即可。\"\\n                                    }\\n                                }\\n                            ],\\n                            \"comment\": \"消息内容\"\\n                        },\\n                        \"image\": {\\n                            \"notnull\": true,\\n                            \"type\": \"object\",\\n                            \"valueLevel\": 0,\\n                            \"values\": [\\n                                {\\n                                    \"id\": {\\n                                        \"notnull\": true,\\n                                        \"type\": \"string\",\\n                                        \"valueLevel\": 3,\\n                                        \"values\": [],\\n                                        \"lengthLevel\": 1,\\n                                        \"lengths\": [\\n                                            1\\n                                        ],\\n                                        \"comment\": \"WhatsApp 生成的 media_id ；id 和 link 其一必须有值。\",\\n                                        \"repeat\": 10\\n                                    },\\n                                    \"link\": {\\n                                        \"notnull\": true,\\n                                        \"type\": \"string\",\\n                                        \"valueLevel\": 3,\\n                                        \"values\": [],\\n                                        \"lengthLevel\": 1,\\n                                        \"lengths\": [\\n                                            53\\n                                        ],\\n                                        \"comment\": \"img.jiguang.cn/jiguang/public/img/c866bd2.png\\\",\",\\n                                        \"repeat\": 10\\n                                    },\\n                                    \"caption\": {\\n                                        \"notnull\": true,\\n                                        \"type\": \"string\",\\n                                        \"valueLevel\": 3,\\n                                        \"values\": [],\\n                                        \"lengthLevel\": 1,\\n                                        \"lengths\": [\\n                                            12\\n                                        ],\\n                                        \"comment\": \"可选，图片下方的文本描述，1024个字符内\",\\n                                        \"repeat\": 10\\n                                    }\\n                                }\\n                            ],\\n                            \"comment\": \"图片,\"\\n                        },\\n                        \"video\": {\\n                            \"notnull\": true,\\n                            \"type\": \"object\",\\n                            \"valueLevel\": 0,\\n                            \"values\": [\\n                                {\\n                                    \"link\": {\\n                                        \"notnull\": true,\\n                                        \"type\": \"string\",\\n                                        \"valueLevel\": 3,\\n                                        \"values\": [],\\n                                        \"lengthLevel\": 1,\\n                                        \"lengths\": [\\n                                            56\\n                                        ],\\n                                        \"comment\": \"img.jiguang.cn/jiguang/public/videos/432acc5.mp4\\\",\",\\n                                        \"repeat\": 9\\n                                    },\\n                                    \"caption\": {\\n                                        \"notnull\": true,\\n                                        \"type\": \"string\",\\n                                        \"valueLevel\": 3,\\n                                        \"values\": [],\\n                                        \"lengthLevel\": 1,\\n                                        \"lengths\": [\\n                                            12\\n                                        ],\\n                                        \"comment\": \"可选，视频下方的文本描述，1024个字符内\",\\n                                        \"repeat\": 9\\n                                    },\\n                                    \"id\": {\\n                                        \"notnull\": true,\\n                                        \"type\": \"string\",\\n                                        \"valueLevel\": 3,\\n                                        \"values\": [],\\n                                        \"lengthLevel\": 1,\\n                                        \"lengths\": [\\n                                            1\\n                                        ],\\n                                        \"comment\": \"WhatsApp 生成的 media_id ；id 和 link 其一必须有值。\",\\n                                        \"repeat\": 8\\n                                    }\\n                                }\\n                            ],\\n                            \"comment\": \"视频\"\\n                        },\\n                        \"audio\": {\\n                            \"notnull\": true,\\n                            \"type\": \"object\",\\n                            \"valueLevel\": 0,\\n                            \"values\": [\\n                                {\\n                                    \"id\": {\\n                                        \"notnull\": true,\\n                                        \"type\": \"string\",\\n                                        \"valueLevel\": 3,\\n                                        \"values\": [],\\n                                        \"lengthLevel\": 1,\\n                                        \"lengths\": [\\n                                            1\\n                                        ],\\n                                        \"comment\": \"WhatsApp 生成的 media_id ；id 和 link 其一必须有值。\",\\n                                        \"repeat\": 8\\n                                    },\\n                                    \"link\": {\\n                                        \"notnull\": true,\\n                                        \"type\": \"string\",\\n                                        \"valueLevel\": 3,\\n                                        \"values\": [],\\n                                        \"lengthLevel\": 1,\\n                                        \"lengths\": [\\n                                            92\\n                                        ],\\n                                        \"comment\": \"file-examples.com/storage/fe5947fd2362fc197a3c2df/2017/11/file_example_MP3_700KB.mp3\\\"\",\\n                                        \"repeat\": 8\\n                                    }\\n                                }\\n                            ],\\n                            \"comment\": \"音频,\"\\n                        },\\n                        \"document\": {\\n                            \"notnull\": true,\\n                            \"type\": \"object\",\\n                            \"valueLevel\": 0,\\n                            \"values\": [\\n                                {\\n                                    \"link\": {\\n                                        \"notnull\": true,\\n                                        \"type\": \"string\",\\n                                        \"valueLevel\": 3,\\n                                        \"values\": [],\\n                                        \"lengthLevel\": 1,\\n                                        \"lengths\": [\\n                                            56\\n                                        ],\\n                                        \"comment\": \"img.jiguang.cn/jiguang/public/videos/432acc5.mp4\\\",\",\\n                                        \"repeat\": 7\\n                                    },\\n                                    \"caption\": {\\n                                        \"notnull\": true,\\n                                        \"type\": \"string\",\\n                                        \"valueLevel\": 3,\\n                                        \"values\": [],\\n                                        \"lengthLevel\": 1,\\n                                        \"lengths\": [\\n                                            12\\n                                        ],\\n                                        \"comment\": \"可选，文件下方的文本描述，1024个字符内\",\\n                                        \"repeat\": 7\\n                                    },\\n                                    \"filename\": {\\n                                        \"notnull\": true,\\n                                        \"type\": \"string\",\\n                                        \"valueLevel\": 3,\\n                                        \"values\": [],\\n                                        \"lengthLevel\": 1,\\n                                        \"lengths\": [\\n                                            18\\n                                        ],\\n                                        \"comment\": \"可选，文件名称\",\\n                                        \"repeat\": 7\\n                                    },\\n                                    \"id\": {\\n                                        \"notnull\": true,\\n                                        \"type\": \"string\",\\n                                        \"valueLevel\": 3,\\n                                        \"values\": [],\\n                                        \"lengthLevel\": 1,\\n                                        \"lengths\": [\\n                                            1\\n                                        ],\\n                                        \"comment\": \"whatsapp 侧的 media_id ；id 和 link 其一必须有值。\",\\n                                        \"repeat\": 6\\n                                    }\\n                                }\\n                            ],\\n                            \"comment\": \"文件消息\"\\n                        },\\n                        \"sticker\": {\\n                            \"notnull\": true,\\n                            \"type\": \"object\",\\n                            \"valueLevel\": 0,\\n                            \"values\": [\\n                                {\\n                                    \"id\": {\\n                                        \"notnull\": true,\\n                                        \"type\": \"string\",\\n                                        \"valueLevel\": 3,\\n                                        \"values\": [],\\n                                        \"lengthLevel\": 1,\\n                                        \"lengths\": [\\n                                            1\\n                                        ],\\n                                        \"comment\": \"whatsapp 侧的 media_id ；id 和 link 其一必须有值。\",\\n                                        \"repeat\": 6\\n                                    },\\n                                    \"link\": {\\n                                        \"notnull\": true,\\n                                        \"type\": \"string\",\\n                                        \"valueLevel\": 3,\\n                                        \"values\": [],\\n                                        \"lengthLevel\": 1,\\n                                        \"lengths\": [\\n                                            65\\n                                        ],\\n                                        \"comment\": \"sample-file.bazadanni.com/download/images/webp/sample.webp\\\"\",\\n                                        \"repeat\": 6\\n                                    }\\n                                }\\n                            ],\\n                            \"comment\": \"贴纸消息\"\\n                        }\\n                    }\\n                ],\\n                \"comment\": \"消息内容\"\\n            },\\n            \"request_id\": {\\n                \"notnull\": true,\\n                \"type\": \"string\",\\n                \"valueLevel\": 3,\\n                \"values\": [],\\n                \"lengthLevel\": 1,\\n                \"lengths\": [\\n                    17\\n                ],\\n                \"repeat\": 11,\\n                \"comment\": \"自定义的请求 ID，用来标识是哪条请求，响应时返回。\"\\n            },\\n            \"custom_args\": {\\n                \"notnull\": true,\\n                \"type\": \"object\",\\n                \"valueLevel\": 0,\\n                \"values\": [\\n                    {\\n                        \"arg1\": {\\n                            \"notnull\": true,\\n                            \"type\": \"string\",\\n                            \"valueLevel\": 3,\\n                            \"values\": [],\\n                            \"lengthLevel\": 1,\\n                            \"lengths\": [\\n                                10\\n                            ],\\n                            \"repeat\": 11\\n                        },\\n                        \"arg2\": {\\n                            \"notnull\": true,\\n                            \"type\": \"integer\",\\n                            \"valueLevel\": 0,\\n                            \"values\": [\\n                                123\\n                            ],\\n                            \"lengthLevel\": 1,\\n                            \"lengths\": [\\n                                3\\n                            ],\\n                            \"repeat\": 22,\\n                            \"trend\": {\\n                                \"top\": 11\\n                            }\\n                        }\\n                    }\\n                ],\\n                \"comment\": \"自定义的信息，在消息状态回调中返回给开发者。\"\\n            }\\n        }\\n    ]\\n}','Authorization: Basic amlndWFuZ2RldjpkZXZfc2VjcmV0','2023-04-25 15:23:06',NULL,'\\n使用消息发送 API 可以将 WhatsApp 的消息发送能力集成到你的业务系统中。<br />在调用 API 之前，请先在控制台 [API 密钥](/zh_CN/docs/whatsapp/console/configuration-management/api-keys) 页面创建密钥。 \\n## 调用地址\\n`POST https://wa.api.engagelab.cc/v1/messages`\\n## 调用验证\\nEngageLab REST API 采用 [HTTP 基本认证](http://zh.wikipedia.org/wiki/HTTP%E5%9F%BA%E6%9C%AC%E8%AE%A4%E8%AF%81) 的验证方式：HTTP Header（头）里加 Authorization：\\n```\\nAuthorization: Basic ${base64_auth_string}\\n```\\n上述 base64_auth_string 的生成算法为：base64(dev_key:dev_secret)\\n\\n- Header 名称是 \"Authorization\"，值是 base64 转换过的 \"username:password\" 对（中间有个冒号）。\\n- 在 WhatsApp API 的场景里，username 是 DevKey，password 是 DevSecret。请在控制台-配置管理- [API 密钥](/zh_CN/docs/whatsapp/console/configuration-management/api-keys) 页面获取。\\n## 请求示例\\n### 请求头\\n```json\\nPOST /v1/messages  \\nHTTP/1.1  Content-Type: application/json  \\nAuthorization: Basic amlndWFuZ2RldjpkZXZfc2VjcmV0\\n```\\n### 请求体\\n```json\\n {\\n    \"from\": \"+8613800138000\",\\n    \"to\": [\\n        \"00447911123456\"\\n    ],\\n    \"body\": {\\n        \"type\": \"template\",\\n        \"template\": {\\n            \"name\": \"code\",\\n            \"language\": \"zh_CN\",\\n            \"components\": [\\n                {\\n                    \"type\": \"body\",\\n                    \"parameters\": [\\n                        {\\n                            \"type\": \"text\",\\n                            \"text\": \"12345\"\\n                        }\\n                    ]\\n                }\\n            ]\\n        }\\n    },\\n    \"request_id\": \"123asdbbqwe9faweg\",\\n    \"custom_args\": {\\n        \"arg1\": \"string val\",\\n        \"arg2\": 123\\n    }\\n}\\n```\\n## 请求参数\\n一个请求对象以 JSON 格式表达，因此请求头需要带 Content-Type: application/json 。\\n\\n| **参数** | **类型** | **选项** | **说明** |\\n| --- | --- | --- | --- |\\n| from | String | 选填 | 发送号 |\\n| to | String Array | 必填 | 发送目标的电话号码 |\\n| body | JSON Object | 必填 | 消息体 |\\n| request_id | String | 选填 | 自定义的请求 ID，用来标识是哪条请求，响应时返回。 |\\n| custom_args | JSON Object | 选填 | 自定义的信息，在消息状态回调中返回给开发者。 |\\n\\n### from\\n| **参数** | **类型** | **选项** | **说明** |\\n| --- | --- | --- | --- |\\n| from | String | 选填 | 发送号，即用于发送消息的企业电话号码。<br />需要加上国际区号，未填写时使用默认发送号（需要在 [控制台配置](/zh_CN/docs/whatsapp/console/configuration-management/sending-numbers#设为默认)） |\\n\\n### to\\n| **参数** | **类型** | **选项** | **说明** |\\n| --- | --- | --- | --- |\\n| to | String Array | 必填 | 发送目标的 WhatsApp 电话号码，需要加上国际区号 |\\n\\n### body\\n一个消息体，包含的字段如下：\\n\\n| **参数** | **类型** | **选项** | **说明** |\\n| --- | --- | --- | --- |\\n| type | string | 必填 | 消息类型，目前支持：<li>template： 模板消息<li>text： 文本消息<li>image： 图片消息<li>audio： 音频消息<li>video： 视频消息<li>document： 文档消息<li>sticker： 贴纸消息<br />**仅 template 消息才能主动发送给用户**，其余类型的消息要求用户在 24 小时内回复过消息，才能被送达。<br />其中 图片/音频/视频/文档/贴纸 皆为媒体消息，注意遵循 [媒体消息格式要求](#媒体消息格式要求)。  |\\n| template | template object | 可选 | 当 type=template 时使用，详见 [template object 说明](#template-object-说明)。 |\\n| text | text object | 可选 | 当 type=text 时使用，详见 [text object 说明](#text-object-说明) |\\n| image | image object | 可选 | 当 type=image 时使用，详见 [image object 说明](#image-object-说明)。 |\\n| audio | audio object | 可选 | 当 type=audio 时使用，详见 [audio object 说明](#audio-object-说明)。 |\\n| video | video object | 可选 | 当 type=video 时使用，详见 [video object 说明](#video-object-说明)。 |\\n| document | document object | 可选 | 当 type=document 时使用，详见 [document object 说明](#document-object-说明)。 |\\n| sticker | sticker object | 可选 | 当 type=sticker 时使用，详见 [sticker object 说明](#sticker-object-说明)。|\\n\\n#### text object 说明\\n文本消息\\n\\n| **参数** | **类型** | 选项 | **说明** |\\n| --- | --- | --- | --- |\\n| body | String | 必填 | 文本内容，WhatsApp 要求不超过 4096 个字符/character |\\n\\n**示例**\\n```\\n{\\n    \"from\": \"8613800138000\", //发送方的电话号码\\n    \"to\": [\"8613800138000\"], //收件人的电话号码\\n    \"body\": {\\n        \"type\": \"text\", //消息类型\\n        \"text\": {\\n            \"body\": \"your-text-message-content\" //消息内容\\n        }\\n    }\\n}\\n```\\n#### image object 说明\\n图片消息\\n\\n| **参数** | **类型** | 选项 | **说明** |\\n| --- | --- | --- | --- |\\n| id | String | 可选 | WhatsApp 生成的 media_id ；id 和 link 其一必须有值。 |\\n| link | String | 可选 | 图片链接，http/https 链接，注意遵循 [媒体消息格式要求](#媒体消息格式要求)。  |\\n| caption | String | 可选 | 对图片的描述，不超过 1024 个字符。 |\\n\\n**示例**\\n```\\n{\\n    \"from\": \"8613800138000\",//发送方的电话号码\\n    \"to\": [\"8613800138000\"], //收件人的电话号码\\n	\"body\": {			\\n			\"type\": \"image\",//消息类型\\n			\"image\": {\\n				\"link\": \"https://img.jiguang.cn/jiguang/public/img/c866bd2.png\", //图片链接\\n        \"caption\": \"caption info\"   // 可选，图片下方的文本描述，1024个字符内\\n			}\\n	}\\n}\\n```\\n#### video object 说明\\n视频消息\\n\\n| **参数** | **类型** | 选项 | **说明** |\\n| --- | --- | --- | --- |\\n| id | String | 可选 | WhatsApp 生成的 media_id ；id 和 link 其一必须有值。 |\\n| link | String | 可选 | 视频链接，http/https 链接，注意遵循 [媒体消息格式要求](#媒体消息格式要求)。  |\\n| caption | String | 可选 | 对视频的描述，不超过 1024 个字符。 |\\n\\n**示例**\\n```\\n{\\n    \"from\": \"8613800138000\",//发送方的电话号码\\n    \"to\": [\"8613800138000\"], //收件人的电话号码\\n	\"body\": {			\\n			\"type\": \"video\",//消息类型\\n			\"video\": {\\n				\"link\": \"https://img.jiguang.cn/jiguang/public/videos/432acc5.mp4\", //视频链接\\n        \"caption\": \"caption info\"   // 可选，视频下方的文本描述，1024个字符内\\n			}\\n	}\\n}\\n```\\n#### audio object 说明\\n音频消息\\n\\n| **参数** | **类型** | 选项 | **说明** |\\n| --- | --- | --- | --- |\\n| id | String | 可选 | WhatsApp 生成的 media_id ；id 和 link 其一必须有值。 |\\n| link | String | 可选 | 音频链接，http/https 链接，注意遵循 [媒体消息格式要求](#媒体消息格式要求)。  |\\n\\n**示例**\\n```\\n{\\n    \"from\": \"8613800138000\",//发送方的电话号码\\n    \"to\": [\"8613800138000\"], //收件人的电话号码\\n	\"body\": {\\n			\"type\": \"audio\",//消息类型\\n			\"audio\": {\\n				\"link\": \"https://file-examples.com/storage/fe5947fd2362fc197a3c2df/2017/11/file_example_MP3_700KB.mp3\" //音频链接\\n			}\\n	}\\n}\\n```\\n#### document object 说明\\n文件消息\\n\\n| **参数** | **类型** | 选项 | **说明** |\\n| --- | --- | --- | --- |\\n| id | String | 可选 | WhatsApp 生成的 media_id ；id 和 link 其一必须有值。 |\\n| link | String | 可选 | 文档链接，http/https 链接，注意遵循 [媒体消息格式要求](#媒体消息格式要求)。  |\\n| caption | String | 可选 | 对文件的描述，不超过 1024 个字符。 |\\n| filename | String | 可选 | 文件名称。若未填写`filename`字段而填写了`caption`字段，则会以`caption`作为文件名；若填写了`filename`则会以`filename`的值作为文件名。 |\\n\\n**示例**\\n```\\n{\\n    \"from\": \"8613800138000\",//发送方的电话号码\\n    \"to\": [\"8613800138000\"], //收件人的电话号码\\n	\"body\": {\\n			\"type\": \"document\",//消息类型\\n			\"document\": {\\n				\"link\": \"https://img.jiguang.cn/jiguang/public/videos/432acc5.mp4\", //文件链接\\n        \"caption\": \"caption info\",   // 可选，文件下方的文本描述，1024个字符内\\n        \"filename\": \"document file name\"    // 可选，文件名称\\n			}\\n	}\\n}\\n```\\n#### sticker object 说明\\n贴纸消息\\n\\n| **参数** | **类型** | 选项 | **说明** |\\n| --- | --- | --- | --- |\\n| id | String | 可选 | whatsapp 侧的 media_id ；id 和 link 其一必须有值。 |\\n| link | String | 可选 | 贴纸链接，http/https 链接，注意遵循 [媒体消息格式要求](#媒体消息格式要求)。  |\\n\\n**示例**\\n```\\n{\\n    \"from\": \"8613800138000\",//发送方的电话号码\\n    \"to\": [\"8613800138000\"], //收件人的电话号码\\n	\"body\": {\\n			\"type\": \"sticker\",//消息类型\\n			\"sticker\": {\\n				\"link\": \"http://sample-file.bazadanni.com/download/images/webp/sample.webp\" //贴纸链接\\n			}\\n	}\\n}\\n```\\n\\n#### template object 说明\\n模板消息，需要先创建模板，可以在 [控制台操作](/zh_CN/docs/whatsapp/console/message-center/message-templates) 或 [调用 API 创建](/zh_CN/docs/whatsapp/rest-api/template-management-api) 。\\n\\n| **参数** | **类型** | **类型** | **说明** |\\n| --- | --- | --- | --- |\\n| name | String | 必填 | 模板名称。可以在控制台-消息模板页面找到，仅支持小写数字及下划线。 |\\n| language | String | 必填 | 模板 [语言代码](https://developers.facebook.com/docs/whatsapp/api/messages/message-templates#language)。创建模板时对同一个模板名称可以设置多个语言的内容，因此发送时需要使用 name 和 language 字段共同决定所选模板。 |\\n| components | components-object array | 可选 | 当模板中存在可变变量时，需要填充此字段，数组中仅设置 1 个 components 对象元素即可。 |\\n\\n##### template.components object 说明\\n| **参数** | **类型** | 选项 | **说明** |\\n| --- | --- | --- | --- |\\n| type | String | 必填 | 模板组件，模板中哪一个组件包含变量，就需要对该组件传值，取值：<li>header：页眉<li>body：正文<li>footer：页脚<li>button：按钮<br /> |\\n| parameters | parameters object | 必填 | 设置可变变量内容 |\\n\\n##### template.components.parameters object 说明\\n| **参数** | **类型** | 选项 | **说明** |\\n| --- | --- | --- | --- |\\n| type | string | 必填 | 变量内容的类型，取值 text、currency、date_time、image、video、document。多媒体素材类型（image、video、document）仅在页眉（header）中存在，素材支持的格式请参考 [媒体消息格式要求](#媒体消息格式要求) 。 |\\n| text | string | 可选 | 当 type=text 时使用，为可变变量的具体内容 |\\n| date_time | localizable object | 可选 | 当 type=date_time 时使用，与 text 区别在于可本地化适配显示。 |\\n| currency | localizable object | 可选 | 当 type=currency 时使用，与 text 区别在于可本地化适配显示。 |\\n| image | image object | 可选 | 当 type=image 时使用，与 [image object](#image-object-说明) 内容格式一致。 |\\n| video | video object | 可选 | 当 type=video 时使用，与 [video object](#video-object-说明) 内容格式一致。 |\\n| document | document object | 可选 | 当 type=document 时使用，与 [document object](#document-object-说明) 内容格式一致。 |\\n\\n\\n**示例**\\n```json\\n{\\n    \"from\": \"+8613800138000\",\\n    \"to\": [\\n        \"00447911123456\"\\n    ],\\n    \"body\": {\\n        \"type\": \"template\",\\n        \"template\": {          \\n            \"name\": \"your-template-name\",\\n						\"language\": \"zh_CN\",\\n            \"components\": [\\n              {\\n                \"type\" : \"header\",\\n                \"parameters\": [{\\n                         \"type\": \"document\",\\n                         \"document\": {\\n                             \"link\": \"http(s)://the-url\",\\n                             \"filename\": \"your-document-filename\"\\n                       }\\n                }]\\n              },\\n              {\\n                 \"type\": \"body\",\\n                 \"parameters\": [\\n                        {\\n                            \"type\": \"text\",\\n                            \"text\": \"your-text-string\"\\n                        },\\n                        {\\n                            \"type\": \"currency\",\\n                            \"currency\": {\\n                                \"fallback_value\": \"$100.99\",\\n                                \"code\": \"USD\",\\n                                \"amount_1000\": 100990\\n                            }\\n                        },\\n                        {\\n                            \"type\": \"date_time\",\\n                            \"date_time\": {\\n                                \"fallback_value\": \"February 25, 1977\",\\n                                \"day_of_week\": 5,\\n                                \"day_of_month\": 25,\\n                                \"year\": 1977,\\n                                \"month\": 2,\\n                                \"hour\": 15,\\n                                \"minute\": 33\\n                            }\\n                        },\\n                        {\\n                            \"type\": \"date_time\",\\n                            \"date_time\": {\\n                                \"fallback_value\": \"February 25, 1977\",\\n                                \"timestamp\": 1485470276\\n                            }\\n                        }\\n                    ]\\n                }\\n            ]\\n        }\\n    }\\n}\\n```\\n## 返回参数\\n### 成功返回\\n| 字段 | 类型 | 选项 | 描述 |\\n| --- | --- | --- | --- |\\n| message_id | String | 必选 | EngageLab WhatsApp 的消息 ID，唯一标识某一条消息。 |\\n| request_id | String | 可选 | 请求时提交的自定义 ID，响应时原样返回。 |\\n\\n```\\n{\\n	\"message_id\": \"cbggf4if6o9ukqaalfug\",\\n	\"request_id\": \"your-sendno-string\"\\n}\\n```\\n### 失败返回\\nhttp 状态码为 4xx 或者 5xx，响应体包含字段如下：\\n\\n| 字段 | 类型 | 选项 | 描述 |\\n| --- | --- | --- | --- |\\n| code | int | 必选 | 错误码，详见 [错误码](#错误码) 说明 |\\n| message | String | 必选 | 错误详情 |\\n\\n```\\n{\\n	\"code\": 3002,\\n	\"message\": \"whatsapp.template field must be set correctly when type is template\"\\n}\\n```\\n## 错误码\\n| **错误码** | **http code** | **说明** |\\n| --- | --- | --- |\\n| 1000 | 500 | 内部错误 |\\n| 2001 | 401 | EngageLab 侧鉴权失败，未携带有效数据格式的 token。 |\\n| 2002 | 401 | EngageLab 侧鉴权失败，token已过期或已被禁用。 |\\n| 2003 | 400 | WhatsApp 侧鉴权失败，请联系 EngageLab 客服处理 。|\\n| 2004 | 403 | 无调用此 API 的权限，请检查您是否有对该 API 秘钥授权了消息发送 API （某发送号）的权限。 |\\n| 3001 | 400 | 请求参数格式无效，请检查是否采用 JSON 格式。 |\\n| 3002 | 400 | 请求参数有误，请检查请求参数是否符合要求。 |\\n| 3003 | 400 | 请求参数有误，相关业务校验失败，详情参考 message 字段的错误描述。 |\\n| 4001 | 400 | 相关资源不存在，如模版消息下发时使用了不存在的模版。 |\\n\\n## 注释\\n### 媒体消息格式要求\\n| **媒体类型** | **支持的格式类型 Content-Type** | 大小限制 |\\n| --- | --- | --- |\\n| image | image/jpeg, image/png，不支持透明背景 | 5 MB |\\n| video | video/mp4, video/3gpp<br />注：编码上仅支持 H.264 视频编码和 AAC 音频编码 | 16MB  |\\n| audio | audio/aac, audio/mp4, audio/amr, audio/mpeg, <br />audio/ogg; codecs=opus（注：基础的 audio/ogg 不支持，仅支持 audio/ogg; codecs=opus） | 16MB |\\n| document | 1、发送文件消息时，支持任何的 MIME-type 类型<br />2、发送模板消息时，页眉中的文件仅支持 PDF 格式 | 100 MB |\\n| sticker | image/webp | Static stickers:100KB<br />Animated stickers: 500KB<br />512x512 像素 |\\n\\n### 语言代码\\n相关语言和对应代码的对应关系，请下载本文件查看：<br />[模板语言代码.xlsx](https://jiguang-docs.yuque.com/attachments/yuque/0/2023/xlsx/22807620/1678169411547-ecc7b449-3d5a-429c-ad7a-96dae3c3284b.xlsx?_lake_card=%7B%22src%22%3A%22https%3A%2F%2Fjiguang-docs.yuque.com%2Fattachments%2Fyuque%2F0%2F2023%2Fxlsx%2F22807620%2F1678169411547-ecc7b449-3d5a-429c-ad7a-96dae3c3284b.xlsx%22%2C%22name%22%3A%22%E6%A8%A1%E6%9D%BF%E8%AF%AD%E8%A8%80%E4%BB%A3%E7%A0%81.xlsx%22%2C%22size%22%3A12877%2C%22ext%22%3A%22xlsx%22%2C%22source%22%3A%22%22%2C%22status%22%3A%22done%22%2C%22download%22%3Atrue%2C%22taskId%22%3A%22ud74a0dec-0013-4792-b890-10f5fb9e6fc%22%2C%22taskType%22%3A%22upload%22%2C%22type%22%3A%22application%2Fvnd.openxmlformats-officedocument.spreadsheetml.sheet%22%2C%22__spacing%22%3A%22both%22%2C%22mode%22%3A%22title%22%2C%22id%22%3A%22ua06120a3%22%2C%22margin%22%3A%7B%22top%22%3Atrue%2C%22bottom%22%3Atrue%7D%2C%22card%22%3A%22file%22%7D)'),(1682437178141,0,0,82002,'APIJSON.cn',0,3,NULL,'消息回调 API',NULL,'POST','JSON','/v1/jpush','{\\n    \"total\": 1,\\n    \"rows\": [\\n        {\\n            \"message_id\": \"1666165485030094861\",\\n            \"from\": \"\",\\n            \"to\": \"\",\\n            \"server\": \"whatsapp\",\\n            \"channel\": \"whatsapp\",\\n            \"itime\": 1640707579,\\n            \"custom_args\": {},\\n            \"status\": {\\n                \"message_status\": \"delivered\",\\n                \"status_data\": {\\n                    \"msg_time\": 1663432355,\\n                    \"channel_message_id\": \"wamid.123321abcdefed==\",\\n                    \"whatsapp_business_account_id\": \"\",\\n                    \"timezone\": \"\",\\n                    \"plan_user_total\": 2007,\\n                    \"country_code\": \"CN\",\\n                    \"from_phone_id\": \"111111\",\\n                    \"conversation\": {\\n                        \"id\": \"ebe2398cdaa37a0899ca5268b987b0c8\",\\n                        \"origin\": {\\n                            \"type\": \"business_initiated\"\\n                        }\\n                    },\\n                    \"pricing\": {\\n                        \"pricing_model\": \"CBP\",\\n                        \"category\": \"business_initiated\"\\n                    }\\n                },\\n                \"error_code\": 0,\\n                \"error_detail\": {\\n                    \"message\": \"\"\\n                },\\n                \"loss\": {\\n                    \"loss_step\": 1,\\n                    \"loss_source\": \"aa\"\\n                }\\n            }\\n        }\\n    ]\\n}',NULL,NULL,'{\\n    \"notnull\": true,\\n    \"type\": \"object\",\\n    \"valueLevel\": 0,\\n    \"values\": [\\n        {\\n            \"total\": {\\n                \"notnull\": true,\\n                \"type\": \"integer\",\\n                \"valueLevel\": 0,\\n                \"values\": [\\n                    1\\n                ],\\n                \"lengthLevel\": 1,\\n                \"lengths\": [\\n                    1\\n                ],\\n                \"repeat\": 14,\\n                \"trend\": {\\n                    \"top\": 7\\n                },\\n                \"comment\": \"回调的数据量\"\\n            },\\n            \"rows\": {\\n                \"notnull\": true,\\n                \"type\": \"array\",\\n                \"valueLevel\": 0,\\n                \"lengthLevel\": 1,\\n                \"lengths\": [\\n                    1\\n                ],\\n                \"values\": [\\n                    {\\n                        \"0\": {\\n                            \"values\": [\\n                                {\\n                                    \"type\": \"number\",\\n                                    \"notnull\": false,\\n                                    \"message_id\": {\\n                                        \"type\": \"string\",\\n                                        \"notnull\": true,\\n                                        \"comment\": \"极光侧的消息 id\"\\n                                    },\\n                                    \"from\": {\\n                                        \"type\": \"string\",\\n                                        \"notnull\": true,\\n                                        \"comment\": \"发送方，即客户的手机号码\"\\n                                    },\\n                                    \"to\": {\\n                                        \"type\": \"string\",\\n                                        \"notnull\": true,\\n                                        \"comment\": \"接收方，即开发者的发送号\"\\n                                    },\\n                                    \"itime\": {\\n                                        \"type\": \"integer\",\\n                                        \"notnull\": true,\\n                                        \"comment\": \"时间戳\"\\n                                    },\\n                                    \"custom_args\": {\\n                                        \"type\": \"object\",\\n                                        \"notnull\": true,\\n                                        \"comment\": \"这条消息创建时提交的参数，将于此回调时原样返回\"\\n                                    },\\n                                    \"status\": {\\n                                        \"type\": \"object\",\\n                                        \"notnull\": true,\\n                                        \"comment\": \"成功时响应这些字段\",\\n                                        \"values\": [\\n                                            {\\n                                                \"0\": {\\n                                                    \"type\": \"string\",\\n                                                    \"notnull\": true,\\n                                                    \"comment\": \"失败状态下（无效目标、发送失败、送达失败、未读）返回这些字段\"\\n                                                },\\n                                                \"type\": \"number\",\\n                                                \"notnull\": false,\\n                                                \"message_status\": {\\n                                                    \"type\": \"string\",\\n                                                    \"notnull\": true,\\n                                                    \"comment\": \"消息状态\"\\n                                                },\\n                                                \"status_data\": {\\n                                                    \"type\": \"object\",\\n                                                    \"notnull\": true,\\n                                                    \"comment\": \"自定义\",\\n                                                    \"values\": [\\n                                                        {\\n                                                            \"type\": \"number\",\\n                                                            \"notnull\": false,\\n                                                            \"msg_time\": {\\n                                                                \"type\": \"integer\",\\n                                                                \"notnull\": true,\\n                                                                \"comment\": \"消息下发时间，历史记录上的消息发送时间，即用户调用 API 发送消息-调用 API 成功的那个时间\"\\n                                                            },\\n                                                            \"channel_message_id\": {\\n                                                                \"type\": \"string\",\\n                                                                \"notnull\": true,\\n                                                                \"comment\": \"可选，Meta 返回的 msgid\"\\n                                                            },\\n                                                            \"whatsapp_business_account_id\": {\\n                                                                \"type\": \"string\",\\n                                                                \"notnull\": true,\\n                                                                \"comment\": \"发送号 from 对应的 Whatsapp 商业账户编码\"\\n                                                            },\\n                                                            \"timezone\": {\\n                                                                \"type\": \"string\",\\n                                                                \"notnull\": true,\\n                                                                \"comment\": \"组织时区\"\\n                                                            },\\n                                                            \"plan_user_total\": {\\n                                                                \"type\": \"integer\",\\n                                                                \"notnull\": true,\\n                                                                \"comment\": \"计划目标总数，只有当 message_status=plan 时这个才会有值\"\\n                                                            },\\n                                                            \"country_code\": {\\n                                                                \"type\": \"string\",\\n                                                                \"notnull\": true,\\n                                                                \"comment\": \"接收方手机号码归属的国家/地区代码\"\\n                                                            },\\n                                                            \"from_phone_id\": {\\n                                                                \"type\": \"string\",\\n                                                                \"notnull\": true,\\n                                                                \"comment\": \"发送号码（from）的 ID 标识\"\\n                                                            },\\n                                                            \"conversation\": {\\n                                                                \"type\": \"object\",\\n                                                                \"notnull\": true,\\n                                                                \"comment\": \"可选，会话信息\",\\n                                                                \"values\": [\\n                                                                    {\\n                                                                        \"type\": \"number\",\\n                                                                        \"notnull\": false,\\n                                                                        \"id\": {\\n                                                                            \"type\": \"string\",\\n                                                                            \"notnull\": true,\\n                                                                            \"comment\": \"该条消息所属的 Meta 对话 ID\"\\n                                                                        },\\n                                                                        \"origin\": {\\n                                                                            \"type\": \"object\",\\n                                                                            \"notnull\": false,\\n                                                                            \"comment\": \" 表示是由谁发起的对话。由 type 指定。\",\\n                                                                            \"values\": [\\n                                                                                {\\n                                                                                    \"type\": \"number\",\\n                                                                                    \"notnull\": false\\n                                                                                }\\n                                                                            ]\\n                                                                        }\\n                                                                    }\\n                                                                ]\\n                                                            },\\n                                                            \"pricing\": {\\n                                                                \"type\": \"object\",\\n                                                                \"notnull\": true,\\n                                                                \"comment\": \"可选，价格信息\",\\n                                                                \"values\": [\\n                                                                    {\\n                                                                        \"type\": \"number\",\\n                                                                        \"notnull\": false,\\n                                                                        \"pricing_model\": {\\n                                                                            \"type\": \"string\",\\n                                                                            \"notnull\": false,\\n                                                                            \"comment\": \" 固定取值为 CBP\"\\n                                                                        },\\n                                                                        \"category\": {\\n                                                                            \"type\": \"string\",\\n                                                                            \"notnull\": true,\\n                                                                            \"comment\": \"对话定价类别，取值如下：business_initiated：商家对话。customer_initiated： 用户对话。referral_conversion： 免费接入点对话。\"\\n                                                                        }\\n                                                                    }\\n                                                                ]\\n                                                            }\\n                                                        }\\n                                                    ]\\n                                                },\\n                                                \"error_code\": {\\n                                                    \"type\": \"integer\",\\n                                                    \"notnull\": true,\\n                                                    \"comment\": \"错误码\"\\n                                                },\\n                                                \"error_detail\": {\\n                                                    \"values\": [\\n                                                        {\\n                                                            \"type\": \"number\",\\n                                                            \"notnull\": false,\\n                                                            \"message\": {\\n                                                                \"type\": \"string\",\\n                                                                \"notnull\": true,\\n                                                                \"comment\": \"错误原因\"\\n                                                            }\\n                                                        }\\n                                                    ]\\n                                                },\\n                                                \"loss\": {\\n                                                    \"values\": [\\n                                                        {\\n                                                            \"type\": \"number\",\\n                                                            \"notnull\": false,\\n                                                            \"loss_step\": {\\n                                                                \"type\": \"integer\",\\n                                                                \"notnull\": true,\\n                                                                \"comment\": \"折损阶段：1：计划目标 ~ 有效目标，即无效目标。2：有效目标 ~ 发送，即发送失败。3：发送 ~ 送达。即送达失败。\"\\n                                                            },\\n                                                            \"loss_source\": {\\n                                                                \"type\": \"string\",\\n                                                                \"notnull\": true,\\n                                                                \"comment\": \"折损来源，取值：engagelab：EngageLab WhatsApp 服务进行校验产生的折损。meta：Meta 官方返回的错误。\"\\n                                                            }\\n                                                        }\\n                                                    ]\\n                                                }\\n                                            }\\n                                        ]\\n                                    },\\n                                    \"server\": {\\n                                        \"type\": \"string\",\\n                                        \"notnull\": true,\\n                                        \"comment\": \"回调信息所属的产品服务，固定取值 whatsapp\"\\n                                    },\\n                                    \"channel\": {\\n                                        \"type\": \"string\",\\n                                        \"notnull\": false,\\n                                        \"comment\": \" 该状态或者响应属于哪一个通道，固定取值 whatsapp\"\\n                                    },\\n                                    \"response\": {\\n                                        \"values\": [\\n                                            {\\n                                                \"type\": \"number\",\\n                                                \"notnull\": false,\\n                                                \"event\": {\\n                                                    \"type\": \"string\",\\n                                                    \"notnull\": true,\\n                                                    \"comment\": \"响应事件\"\\n                                                },\\n                                                \"response_data\": {\\n                                                    \"type\": \"object\",\\n                                                    \"notnull\": true,\\n                                                    \"comment\": \"具体消息内容\",\\n                                                    \"values\": [\\n                                                        {\\n                                                            \"type\": \"number\",\\n                                                            \"notnull\": false,\\n                                                            \"channel_message_id\": {\\n                                                                \"type\": \"string\",\\n                                                                \"notnull\": true,\\n                                                                \"comment\": \"可选，Meta 返回的 msgid\"\\n                                                            },\\n 