--
-- Table structure for table `TestRecord`
--

DROP TABLE IF EXISTS `TestRecord`;
CREATE TABLE `TestRecord` (
  `id` bigint NOT NULL COMMENT '唯一标识',
  `invalid` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否无效，仅供展示自动化测试报告使用：0-有效 1-无效',
  `from` tinyint NOT NULL DEFAULT '0' COMMENT '来源：0-接口工具；1-CI/CD；2-流量录制',
  `userId` bigint NOT NULL COMMENT '用户id',
  `testAccountId` bigint NOT NULL DEFAULT '0',
  `chainGroupId` bigint NOT NULL DEFAULT '0',
  `chainId` bigint NOT NULL DEFAULT '0',
  `documentId` bigint NOT NULL COMMENT '测试用例文档id',
  `randomId` bigint NOT NULL DEFAULT '0' COMMENT '随机配置 id',
  `reportId` bigint NOT NULL DEFAULT '0' COMMENT '测试结果统计报告 ID',
  `host` varchar(1000) DEFAULT NULL,
  `date` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建日期',
  `duration` bigint DEFAULT NULL COMMENT '服务处理耗时，单位为毫秒(ms)',
  `minDuration` bigint DEFAULT NULL COMMENT '统计过的最短服务处理耗时，单位为毫秒(ms)',
  `maxDuration` bigint DEFAULT NULL COMMENT '统计过的最长服务处理耗时，单位为毫秒(ms)',
  `total` int DEFAULT NULL,
  `correct` int DEFAULT NULL,
  `wrong` int DEFAULT NULL,
  `miss` int DEFAULT NULL,
  `score` int DEFAULT NULL,
  `iou` int DEFAULT NULL,
  `recall` double DEFAULT NULL,
  `precision` double DEFAULT NULL,
  `f1` double DEFAULT NULL,
  `corrects` json DEFAULT NULL,
  `wrongs` json DEFAULT NULL,
  `sameIds` json DEFAULT NULL COMMENT '和之前结果一样的 TestRecord id',
  `missTruth` json DEFAULT NULL COMMENT '漏检的 bbox, polygon, line, point 等详情，和 response 里的组合起来就是完整的 Ground Truth',
  `compare` text COMMENT '对比结果',
  `header` varchar(1000) DEFAULT NULL,
  `response` text NOT NULL COMMENT '接口返回结果JSON',
  `standard` text COMMENT 'response 的校验标准，是一个 JSON 格式的 AST ，描述了正确 Response 的结构、里面的字段名称、类型、长度、取值范围 等属性。',
  PRIMARY KEY (`id`)
);

CREATE INDEX `idx_TestRecord_index_documentId` ON `TestRecord` (`documentId`);
CREATE INDEX `idx_TestRecord_index_randomId` ON `TestRecord` (`randomId`);
CREATE INDEX `idx_TestRecord_index_date` ON `TestRecord` (`date`);

