--
-- Table structure for table `Random`
--

DROP TABLE IF EXISTS `Random`;
CREATE TABLE `Random` (
  `id` bigint NOT NULL COMMENT '唯一标识',
  `toId` bigint NOT NULL DEFAULT '0' COMMENT '父项 id',
  `from` tinyint NOT NULL DEFAULT '0' COMMENT '来源：0-接口工具；1-CI/CD；2-流量录制',
  `userId` bigint NOT NULL,
  `chainGroupId` bigint NOT NULL DEFAULT '0',
  `chainId` bigint NOT NULL DEFAULT '0',
  `documentId` bigint NOT NULL COMMENT '测试用例 Document 的 id',
  `count` int NOT NULL DEFAULT '1' COMMENT '请求次数，默认 1',
  `name` varchar(100) NOT NULL COMMENT '名称',
  `config` varchar(5000) NOT NULL COMMENT '配置',
  `date` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `img` longtext,
  `file` varchar(200) DEFAULT NULL,
  `size` bigint NOT NULL DEFAULT '0',
  `width` int DEFAULT NULL,
  `height` int DEFAULT NULL,
  `rank` bigint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`)
);

CREATE INDEX `idx_Random_index_date` ON `Random` (`date`);
CREATE INDEX `idx_Random_index_documentId` ON `Random` (`documentId`);
CREATE INDEX `idx_Random_index_toId` ON `Random` (`toId`);
CREATE INDEX `idx_Random_index_documentId_toId` ON `Random` (`documentId`,`toId`);

